static void stencil_step(int x0, int x1, int y0, int y1, int z0, int z1, int Nx, int Ny, int Nz, const float coef[4],
                         const float vsq[], const float Ain[], float Aout[]) {
    int Nxy = Nx * Ny;

    for (int z = z0; z < z1; ++z) {
        for (int y = y0; y < y1; ++y) {
            for (int x = x0; x < x1; ++x) {
                int index = (z * Nxy) + (y * Nx) + x;
#define A_cur(x, y, z) Ain[index + (x) + ((y)*Nx) + ((z)*Nxy)]
#define A_next(x, y, z) Aout[index + (x) + ((y)*Nx) + ((z)*Nxy)]
                float div = coef[0] * A_cur(0, 0, 0) +
                            coef[1] * (A_cur(+1, 0, 0) + A_cur(-1, 0, 0) + A_cur(0, +1, 0) + A_cur(0, -1, 0) +
                                       A_cur(0, 0, +1) + A_cur(0, 0, -1)) +
                            coef[2] * (A_cur(+2, 0, 0) + A_cur(-2, 0, 0) + A_cur(0, +2, 0) + A_cur(0, -2, 0) +
                                       A_cur(0, 0, +2) + A_cur(0, 0, -2)) +
                            coef[3] * (A_cur(+3, 0, 0) + A_cur(-3, 0, 0) + A_cur(0, +3, 0) + A_cur(0, -3, 0) +
                                       A_cur(0, 0, +3) + A_cur(0, 0, -3));

                A_next(0, 0, 0) = 2 * A_cur(0, 0, 0) - A_next(0, 0, 0) + vsq[index] * div;
            }
        }
    }
}

static void stencil_row(int x0, int x1, int y, int z, int Nx, int Ny, const float coef[4],
                        const float vsq[], const float Ain[], float Aout[]) {
    int Nxy = Nx * Ny;

    for (int x = x0; x < x1; ++x) {
        int index = (z * Nxy) + (y * Nx) + x;
        float div = coef[0] * A_cur(0, 0, 0) +
                    coef[1] * (A_cur(+1, 0, 0) + A_cur(-1, 0, 0) + A_cur(0, +1, 0) + A_cur(0, -1, 0) +
                               A_cur(0, 0, +1) + A_cur(0, 0, -1)) +
                    coef[2] * (A_cur(+2, 0, 0) + A_cur(-2, 0, 0) + A_cur(0, +2, 0) + A_cur(0, -2, 0) +
                               A_cur(0, 0, +2) + A_cur(0, 0, -2)) +
                    coef[3] * (A_cur(+3, 0, 0) + A_cur(-3, 0, 0) + A_cur(0, +3, 0) + A_cur(0, -3, 0) +
                               A_cur(0, 0, +3) + A_cur(0, 0, -3));

        A_next(0, 0, 0) = 2 * A_cur(0, 0, 0) - A_next(0, 0, 0) + vsq[index] * div;
    }
}
#undef A_cur
#undef A_next

void loop_stencil_serial(int t0, int t1, int x0, int x1, int y0, int y1, int z0, int z1, int Nx, int Ny, int Nz,
                         const float coef[4], const float vsq[], float Aeven[], float Aodd[]) {
    for (int t = t0; t < t1; ++t) {
        if ((t & 1) == 0)
            stencil_step(x0, x1, y0, y1, z0, z1, Nx, Ny, Nz, coef, vsq, Aeven, Aodd);
        else
            stencil_step(x0, x1, y0, y1, z0, z1, Nx, Ny, Nz, coef, vsq, Aodd, Aeven);
    }
}

#include <algorithm>
#include <cstddef>
#include <cstring>
#include <omp.h>

extern "C" void run(const void* input1, const void* input2, void* output, int n, int parameter, int threads) {
    const std::size_t s = static_cast<std::size_t>(n) * n * n;
    const float* a = static_cast<const float*>(input1);
    float* c = static_cast<float*>(output);
    std::memcpy(c, a, s * sizeof(float));
    std::memset(c + s, 0, s * sizeof(float));

    const float co[4] = {0.5f, -0.25f, 0.125f, -0.0625f};
    const float* vsq = static_cast<const float*>(input2);
    const int x0 = 4;
    const int x1 = n - 4;
    const int y0 = 4;
    const int y1 = n - 4;
    const int z0 = 4;
    const int z1 = n - 4;
    const int active_x = std::max(0, x1 - x0);
    const int active_y = std::max(0, y1 - y0);
    const int active_z = std::max(0, z1 - z0);
    const std::size_t active_cells = static_cast<std::size_t>(active_x) * active_y * active_z;

    if (threads <= 0 || active_cells < 32768) {
        loop_stencil_serial(0, 6, x0, x1, y0, y1, z0, z1, n, n, n, co, vsq, c, c + s);
        return;
    }

    const std::size_t row_count = static_cast<std::size_t>(active_y) * active_z;
    const int team_size = static_cast<int>(std::min(static_cast<std::size_t>(threads), row_count));

    if (threads == 1) {
        for (int t = 0; t < 6; ++t) {
            const float* Ain = (t & 1) == 0 ? c : c + s;
            float* Aout = (t & 1) == 0 ? c + s : c;

#pragma omp parallel for schedule(static) num_threads(team_size)
            for (std::size_t row = 0; row < row_count; ++row) {
                const int y = y0 + static_cast<int>(row % static_cast<std::size_t>(active_y));
                const int z = z0 + static_cast<int>(row / static_cast<std::size_t>(active_y));
                stencil_row(x0, x1, y, z, n, n, co, vsq, Ain, Aout);
            }
        }
    } else {
#pragma omp parallel num_threads(team_size)
        {
            for (int t = 0; t < 6; ++t) {
                const float* Ain = (t & 1) == 0 ? c : c + s;
                float* Aout = (t & 1) == 0 ? c + s : c;

#pragma omp for schedule(static)
                for (std::size_t row = 0; row < row_count; ++row) {
                    const int y = y0 + static_cast<int>(row % static_cast<std::size_t>(active_y));
                    const int z = z0 + static_cast<int>(row / static_cast<std::size_t>(active_y));
                    stencil_row(x0, x1, y, z, n, n, co, vsq, Ain, Aout);
                }
            }
        }
    }
}
